pub enum Command {
    /// 显示/切换背景
    ShowBackground {
        /// 背景图片路径
        path: String,
        /// 过渡效果（可选）
        transition: Option<Transition>,
    },

    /// 切换场景（可带 rule 遮罩）
    ChangeScene {
        /// 场景图片路径
        path: String,
        /// 过渡效果（可选）
        transition: Option<Transition>,
    },

    /// 显示角色立绘
    ShowCharacter {
        /// 立绘图片路径
        path: String,
        /// 角色别名（用于后续引用）
        alias: String,
        /// 显示位置
        position: Position,
        /// 过渡效果（可选）
        transition: Option<Transition>,
    },

    /// 隐藏角色立绘
    HideCharacter {
        /// 角色别名
        alias: String,
        /// 过渡效果（可选）
        transition: Option<Transition>,
    },

    /// 显示对话文本
    ShowText {
        /// 说话者名称（None 表示旁白）
        speaker: Option<String>,
        /// 对话内容（纯文本，标签已剥离）
        content: String,
        /// 内联效果列表
        inline_effects: Vec<InlineEffect>,
        /// 是否自动推进（行尾 `-->` 修饰符）
        no_wait: bool,
    },

    /// 台词续接（不清屏追加文本）
    ExtendText {
        /// 追加文本（纯文本）
        content: String,
        /// 内联效果列表
        inline_effects: Vec<InlineEffect>,
        /// 是否自动推进
        no_wait: bool,
    },

    /// 显示选择分支
    PresentChoices {
        /// 选择界面样式（从表头提取）
        style: Option<String>,
        /// 选项列表
        choices: Vec<Choice>,
    },

    /// 播放背景音乐
    PlayBgm {
        /// 音乐文件路径
        path: String,
        /// 是否循环播放
        looping: bool,
    },

    /// 停止背景音乐
    StopBgm {
        /// 淡出时长（秒），None 表示立即停止
        fade_out: Option<f64>,
    },

    /// 压低 BGM 音量（duck）
    BgmDuck,

    /// 恢复 BGM 音量（unduck）
    BgmUnduck,

    /// 播放音效
    PlaySfx {
        /// 音效文件路径
        path: String,
    },

    /// 章节标记（用于显示章节过渡动画）
    ChapterMark {
        /// 章节标题
        title: String,
        /// 章节级别（1-6，对应 # 到 ######）
        level: u8,
    },

    /// 隐藏对话框（不影响背景/立绘）
    TextBoxHide,

    /// 显示对话框
    TextBoxShow,

    /// 清理对话框内容（对话/选择分支等）
    TextBoxClear,

    /// 清除所有角色立绘
    ClearCharacters,

    /// 场景效果（镜头语言）
    ///
    /// Host 收到此命令后应按 `name` 分发到对应的效果处理器。
    /// 参数格式复用 `Transition` 的 args 结构。
    SceneEffect {
        /// 效果名称（如 "shakeSmall", "blurIn"）
        name: String,
        /// 效果参数
        args: Vec<(Option<String>, TransitionArg)>,
    },

    /// 章节字卡
    ///
    /// Host 收到后全屏居中显示文字，淡入淡出后自动消失。
    TitleCard {
        /// 显示文本
        text: String,
        /// 显示时长（秒）
        duration: f64,
    },

    /// 完整重启游戏会话
    ///
    /// Host 收到此命令后应：
    /// 1. 将 `RuntimeState.persistent_variables` 持久化到 `saves/persistent.json`
    /// 2. 清空当前游戏会话
    /// 3. 返回标题画面
    FullRestart,

    /// 播放过场视频
    ///
    /// Host 收到后全屏播放指定视频。播放完毕或玩家跳过后，
    /// 发送 `Signal("cutscene")` 恢复 Runtime。
    /// `FFmpeg` 不可用或文件不存在时应优雅降级（跳过 + 警告）。
    Cutscene {
        /// 视频文件路径
        path: String,
    },

    /// 切换文本显示模式
    ///
    /// Host 收到后切换对话渲染方式。
    /// 切换到 NVL 时开始累积对话文本。
    /// 切换到 ADV 时清空累积的 NVL 文本。
    SetTextMode(TextMode),

    /// 请求 Host 展示自定义 UI 并等待用户交互
    ///
    /// Host 收到后应根据 `mode` 展示对应 UI，用户完成交互后
    /// 通过 `RuntimeInput::UIResult { key, value }` 回传结果。
    RequestUI {
        /// 请求标识符（用于匹配响应）
        key: String,
        /// UI 模式标识（Host 据此选择展示哪种 UI）
        mode: String,
        /// 模式特定参数
        params: HashMap<String, VarValue>,
    },
}

#[cfg(test)]
mod tests;
